public class LoadPeriods {
    public void load(@Val Sheet sheet, PeriodRepository repository, Out<List<Period>> periods) {
        periods.set(repository.findAll(sheet.id()));
    }
}
package net.officefloor.hq.app.period;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.LocalDate;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class PeriodRepository {

    private static final String COLUMNS = "sheet_id, name, from_date, to_date, closed, closed_total, soft_closed, claim_cap, locked";

    private final JdbcTemplate jdbc;

    public PeriodRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's periods, earliest first. */
    public List<Period> findAll(String sheetId) {
        List<Period> periods = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? ORDER BY from_date",
                PeriodRepository::map, sheetId);
        Map<String, Map<Long, BigDecimal>> totals = new HashMap<>();
        Map<String, Map<Long, BigDecimal>> carried = new HashMap<>();
        jdbc.query("SELECT period_name, person_id, total, carried FROM period_person_total WHERE sheet_id = ?",
                (rs) -> {
                    totals.computeIfAbsent(rs.getString("period_name"), (k) -> new HashMap<>())
                            .put(rs.getLong("person_id"), rs.getBigDecimal("total"));
                    carried.computeIfAbsent(rs.getString("period_name"), (k) -> new HashMap<>())
                            .put(rs.getLong("person_id"), rs.getBigDecimal("carried"));
                }, sheetId);
        return periods.stream().map((p) -> p.withPersonTotals(totals.getOrDefault(p.name(), Map.of()),
                carried.getOrDefault(p.name(), Map.of()))).toList();
    }

    /** The sheet's period with this name, or null. */
    public Period find(String sheetId, String name) {
        List<Period> found = jdbc.query("SELECT " + COLUMNS + " FROM period WHERE sheet_id = ? AND name = ?",
                PeriodRepository::map, sheetId, name);
        if (found.isEmpty()) {
            return null;
        }
        Map<Long, BigDecimal> totals = new HashMap<>();
        Map<Long, BigDecimal> carried = new HashMap<>();
        jdbc.query("SELECT person_id, total, carried FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                (rs) -> {
                    totals.put(rs.getLong("person_id"), rs.getBigDecimal("total"));
                    carried.put(rs.getLong("person_id"), rs.getBigDecimal("carried"));
                }, sheetId, found.get(0).name());
        return found.get(0).withPersonTotals(totals, carried);
    }

    /** The sheet's closed period containing the date, or null. */
    public Period closedOn(String sheetId, LocalDate date) {
        return findAll(sheetId).stream().filter((p) -> p.closed() && p.contains(date)).findFirst().orElse(null);
    }

    /** The sheet's soft-closed period containing the date, or null. */
    public Period softClosedOn(String sheetId, LocalDate date) {
        return findAll(sheetId).stream().filter((p) -> p.softClosed() && p.contains(date)).findFirst().orElse(null);
    }

    /** Where each of the sheet's periods stands in the order they were added, by name (higher is later). */
    public Map<String, Long> addedOrder(String sheetId) {
        Map<String, Long> order = new HashMap<>();
        jdbc.query("SELECT name, id FROM period WHERE sheet_id = ?",
                (rs) -> {
                    order.put(rs.getString("name"), rs.getLong("id"));
                }, sheetId);
        return order;
    }

    public void insert(Period period) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date, claim_cap) VALUES (?, ?, ?, ?, ?)",
                period.sheetId(), period.name(), period.from(), period.to(), period.cap());
    }

    /** Store the period's closed and soft-closed flags, fixed due-total (null when reopened) and fixed per-person due-totals and carried figures. */
    public void saveClosed(Period period) {
        jdbc.update("UPDATE period SET closed = ?, closed_total = ?, soft_closed = ? WHERE sheet_id = ? AND name = ?",
                period.closed(), period.closedTotal(), period.softClosed(), period.sheetId(), period.name());
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?",
                period.sheetId(), period.name());
        period.personTotals().forEach((personId, total) -> jdbc.update(
                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total, carried) VALUES (?, ?, ?, ?, ?)",
                period.sheetId(), period.name(), personId, total,
                period.personCarried().getOrDefault(personId, BigDecimal.ZERO.setScale(2))));
    }

    /** Store the period's locked flag. */
    public void saveLocked(Period period) {
        jdbc.update("UPDATE period SET locked = ? WHERE sheet_id = ? AND name = ?", period.locked(), period.sheetId(),
                period.name());
    }

    private static Period map(ResultSet rs, int n) throws SQLException {
        return new Period(rs.getString("sheet_id"), rs.getString("name"), rs.getObject("from_date", LocalDate.class),
                rs.getObject("to_date", LocalDate.class), rs.getBoolean("closed"), rs.getBigDecimal("closed_total"), Map.of(),
                rs.getBoolean("soft_closed"), rs.getObject("claim_cap", Integer.class), Map.of(),
                rs.getBoolean("locked"));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.plugin.variable.Val;

/** Refuses (400) any change to a claim whose due-by falls inside a closed period (its period is the one containing its due-by). */
public class CheckClaimPeriodOpen {
    public void check(@Val Claim claim, PeriodRepository periods) throws InvalidClaimException {
        Period closed = periods.closedOn(claim.sheetId(), claim.dueBy());
        if (closed != null) {
            throw new InvalidClaimException("The claim is due by " + claim.dueBy() + ", in the closed period " + closed.name() + ".");
        }
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Refuses (400) a claim about to be added whose due-by — its date (blank: the sheet's entry date, else its today)
 * plus the terms it would get (see {@link NewDueBy}) — falls inside a closed period. */
public class CheckClaimInputPeriodOpen {
    public void check(@Val ClaimInput input, @Val Person person, @PathVariable("sheetId") String sheetId,
            SheetRepository sheets, SettingRepository settings, HolidayRepository holidays, PeriodRepository periods)
            throws InvalidClaimException {
        LocalDate date = input.date() != null ? input.date() : sheets.entryDate(sheetId);
        LocalDate dueBy = NewDueBy.of(date, person, sheets, settings, holidays);
        Period closed = periods.closedOn(sheetId, dueBy);
        if (closed != null) {
            throw new InvalidClaimException("A claim dated " + date + " is due by " + dueBy
                    + ", in the closed period " + closed.name() + ".");
        }
    }
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { poolsKey } from '../pools/pools';
import { useRates } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useDueRules, useSettings } from '../settings/settings';
import { fiscalYearOf, periodDue, periodsKey, usePeriods } from './periods';
import type { Period, PeriodInput } from './periods';
import { useOneAtATime } from '../../query/useOneAtATime';

const EMPTY: PeriodInput = { name: '', from: '', to: '', cap: '' };

/** yyyy-MM-dd. */
const DATE = /^\d{4}-\d{2}-\d{2}$/;

// The sheet's periods, each with its due-total, and the form that adds one.
export function Periods() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const periods = usePeriods().data ?? [];
  const claims = useClaims().data ?? [];
  const people = usePeople().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const fiscalStartMonth = Number(useSettings().data?.fiscalStartMonth || 1);
  const [form, setForm] = useState<PeriodInput>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const add = useMutation({
    mutationFn: (input: PeriodInput) =>
      postJson<Period>(`/api/sheets/${encodeURIComponent(sheet)}/periods?user=${encodeURIComponent(user)}`, input),
    onSuccess: async () => {
      setForm(EMPTY);
      setError('');
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet) });
    },
    onError: () => setError('That period could not be added: its name must be new and its dates must not overlap another period.'),
  });

  // The generate form: one period per calendar month from the from-date's month to the to-date's month.
  const [gen, setGen] = useState({ from: '', to: '' });
  const [genError, setGenError] = useState('');
  const [made, setMade] = useState<number | undefined>(undefined);
  const generate = useMutation({
    mutationFn: (input: { from: string; to: string }) =>
      postJson<{ made: number }>(
        `/api/sheets/${encodeURIComponent(sheet)}/generate-periods?user=${encodeURIComponent(user)}`,
        input,
      ),
    onSuccess: async (result) => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet) });
      setMade(result.made);
    },
    onError: () => setGenError('No periods were generated: the to-date must not be before the from-date.'),
  });

  // The fiscal year form: the twelve monthly periods of the fiscal year typed, made as the generate form makes them.
  const [fyYear, setFyYear] = useState('');
  const generateFy = useMutation({
    mutationFn: (input: { year: string }) =>
      postJson<{ made: number }>(
        `/api/sheets/${encodeURIComponent(sheet)}/generate-fiscal-year?user=${encodeURIComponent(user)}`,
        input,
      ),
    onSuccess: async (result) => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet) });
      setMade(result.made);
    },
    onError: () => setGenError('No periods were generated: type the fiscal year as yyyy.'),
  });

  // The quarters form: the four calendar quarters of the year typed, named yyyy-Q1 to yyyy-Q4.
  const [quarterYear, setQuarterYear] = useState('');
  const generateQuarters = useMutation({
    mutationFn: (input: { year: string }) =>
      postJson<{ made: number }>(
        `/api/sheets/${encodeURIComponent(sheet)}/generate-quarters?user=${encodeURIComponent(user)}`,
        input,
      ),
    onSuccess: async (result) => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet) });
      setMade(result.made);
    },
    onError: () => setGenError('No periods were generated: type the year as yyyy.'),
  });

  // The period whose close, reopen, lock or unlock was refused, and why; cleared by the next action on a period.
  const [rowError, setRowError] = useState<{ name: string; message: string } | null>(null);
  const act = useMutation({
    mutationFn: ({ name, action }: { name: string; action: 'close' | 'soft-close' | 'reopen' | 'lock' | 'unlock' }) =>
      postJson<Period>(
        `/api/sheets/${encodeURIComponent(sheet)}/periods/${encodeURIComponent(name)}/${action}?user=${encodeURIComponent(user)}`,
        {},
      ),
    onSuccess: async () => {
      // a close or soft-close fixes the pools' cuts for the period, a reopen makes them live again
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheet) });
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheet) });
    },
    onError: (_e, { name, action }) =>
      setRowError({
        name,
        message:
          action === 'close'
            ? 'That period could not be closed: it is already closed, or your role is not allowed to close a period.'
            : action === 'soft-close'
              ? 'That period could not be soft-closed: it is already closed or soft-closed, or your role is not allowed to close a period.'
              : action === 'lock'
                ? 'That period could not be locked: it is already locked, or you are not a steward.'
                : action === 'unlock'
                  ? 'That period could not be unlocked: it is not locked, or you are not a steward.'
                  : 'That period could not be reopened: it is not closed or it is locked, or your role is not allowed to reopen a period.',
      }),
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const input = { name: form.name.trim(), from: form.from.trim(), to: form.to.trim(), cap: form.cap.trim() };
    if (input.name === '') {
      setError('Type a name for the period.');
      return;
    }
    if (!DATE.test(input.from) || !DATE.test(input.to)) {
      setError('Type the from and to dates as yyyy-mm-dd.');
      return;
    }
    if (input.to < input.from) {
      setError('The to-date must not be before the from-date.');
      return;
    }
    if (input.cap !== '' && (!/^\d+$/.test(input.cap) || Number(input.cap) < 1)) {
      setError('Type the cap as a whole number of at least 1, or leave it blank for none.');
      return;
    }
    once(() => add.mutateAsync(input));
  };

  const submitGenerate = (e: FormEvent) => {
    e.preventDefault();
    setGenError('');
    setMade(undefined);
    const input = { from: gen.from.trim(), to: gen.to.trim() };
    if ((input.from && !DATE.test(input.from)) || (input.to && !DATE.test(input.to))) {
      setGenError('Type the from and to dates as yyyy-mm-dd.');
      return;
    }
    if (input.from && input.to && input.to < input.from) {
      setGenError('The to-date must not be before the from-date.');
      return;
    }
    once(() => generate.mutateAsync(input));
  };

  const submitGenerateFy = (e: FormEvent) => {
    e.preventDefault();
    setGenError('');
    setMade(undefined);
    const year = fyYear.trim();
    if (!/^\d{4}$/.test(year)) {
      setGenError('Type the fiscal year as yyyy.');
      return;
    }
    once(() => generateFy.mutateAsync({ year }));
  };

  const submitGenerateQuarters = (e: FormEvent) => {
    e.preventDefault();
    setGenError('');
    setMade(undefined);
    const year = quarterYear.trim();
    if (!/^\d{4}$/.test(year)) {
      setGenError('Type the year as yyyy.');
      return;
    }
    once(() => generateQuarters.mutateAsync({ year }));
  };

  const changeGenerate = (patch: Partial<{ from: string; to: string }>) => {
    setGen((g) => ({ ...g, ...patch }));
    setGenError('');
  };

  const change = (patch: Partial<PeriodInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  return (
    <section data-testid="periods">
      <table data-testid="period-list">
        <thead>
          <tr>
            <th>Period</th>
            <th>From</th>
            <th>To</th>
            <th>Due</th>
            <th>Closed</th>
            <th>Fiscal year</th>
            <th>Cap</th>
            <th>Locked</th>
            <th />
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td data-testid="period-due-total">{periodDue(p, claims, people, rates, rules)}</td>
              <td data-testid="period-closed">{p.closed ? 'yes' : p.soft ? 'soft' : 'no'}</td>
              <td data-testid="period-fy">{fiscalYearOf(p.from, fiscalStartMonth)}</td>
              <td data-testid="period-cap">{p.cap ?? ''}</td>
              <td data-testid="period-locked">{p.locked ? 'yes' : 'no'}</td>
              <td>
                <button
                  type="button"
                  data-testid="period-close"
                  disabled={act.isPending}
                  onClick={() => {
                    setRowError(null);
                    once(() => act.mutateAsync({ name: p.name, action: 'close' }));
                  }}
                >
                  Close
                </button>
                <button
                  type="button"
                  data-testid="period-soft-close"
                  disabled={act.isPending}
                  onClick={() => {
                    setRowError(null);
                    once(() => act.mutateAsync({ name: p.name, action: 'soft-close' }));
                  }}
                >
                  Soft close
                </button>
                <button
                  type="button"
                  data-testid="period-reopen"
                  disabled={act.isPending}
                  onClick={() => {
                    setRowError(null);
                    once(() => act.mutateAsync({ name: p.name, action: 'reopen' }));
                  }}
                >
                  Reopen
                </button>
                <button
                  type="button"
                  data-testid="period-lock"
                  disabled={act.isPending}
                  onClick={() => {
                    setRowError(null);
                    once(() => act.mutateAsync({ name: p.name, action: 'lock' }));
                  }}
                >
                  Lock
                </button>
                <button
                  type="button"
                  data-testid="period-unlock"
                  disabled={act.isPending}
                  onClick={() => {
                    setRowError(null);
                    once(() => act.mutateAsync({ name: p.name, action: 'unlock' }));
                  }}
                >
                  Unlock
                </button>
                {rowError?.name === p.name && <span data-testid="period-error">{rowError.message}</span>}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      <form onSubmit={submit} data-testid="period-form">
        <input
          data-testid="period-form-name"
          placeholder="Period name"
          value={form.name}
          onChange={(e) => change({ name: e.target.value })}
        />
        <input
          data-testid="period-form-from"
          placeholder="From yyyy-mm-dd"
          value={form.from}
          onChange={(e) => change({ from: e.target.value })}
        />
        <input
          data-testid="period-form-to"
          placeholder="To yyyy-mm-dd"
          value={form.to}
          onChange={(e) => change({ to: e.target.value })}
        />
        <input
          data-testid="period-form-cap"
          placeholder="Cap per person (blank: none)"
          value={form.cap}
          onChange={(e) => change({ cap: e.target.value })}
        />
        <button type="submit" data-testid="period-form-submit" disabled={add.isPending}>
          Add period
        </button>
        {error && <span data-testid="period-form-error">{error}</span>}
      </form>
      <form onSubmit={submitGenerate} data-testid="period-generate-form">
        <input
          data-testid="period-generate-from"
          placeholder="From yyyy-mm-dd"
          value={gen.from}
          onChange={(e) => changeGenerate({ from: e.target.value })}
        />
        <input
          data-testid="period-generate-to"
          placeholder="To yyyy-mm-dd"
          value={gen.to}
          onChange={(e) => changeGenerate({ to: e.target.value })}
        />
        <button type="submit" data-testid="period-generate" disabled={generate.isPending}>
          Generate monthly periods
        </button>
        {made !== undefined && (
          <>
            {' '}
            Made <span data-testid="period-generated">{made}</span>
          </>
        )}
        {genError && <span data-testid="period-generate-error">{genError}</span>}
      </form>
      <form onSubmit={submitGenerateFy} data-testid="period-generate-fy-form">
        <input
          data-testid="period-generate-fy-year"
          placeholder="Fiscal year yyyy"
          value={fyYear}
          onChange={(e) => {
            setFyYear(e.target.value);
            setGenError('');
          }}
        />
        <button type="submit" data-testid="period-generate-fy" disabled={generateFy.isPending}>
          Generate fiscal year
        </button>
      </form>
      <form onSubmit={submitGenerateQuarters} data-testid="period-generate-quarters-form">
        <input
          data-testid="period-generate-quarters-year"
          placeholder="Year yyyy"
          value={quarterYear}
          onChange={(e) => {
            setQuarterYear(e.target.value);
            setGenError('');
          }}
        />
        <button type="submit" data-testid="period-generate-quarters" disabled={generateQuarters.isPending}>
          Generate quarters
        </button>
      </form>
    </section>
  );
}

